+                     << " has no counterpart in semantic." << to_mode);
+                CHECK((to.contains(group) && to.at(group).contains(name)));
+            }
+    };
+    require_mirror(light, "light", dark, "dark");
+    require_mirror(dark, "dark", light, "light");
+}
